import * as THREE from 'three';

/**
 * Registry of couplings: driver gear -> array of driven gears (in coupling order).
 * Used to reconstruct the ordered train chain for driveTrain().
 */
const couplings = new WeakMap();
/** driven gear -> its driver, so we can walk back to the head of the chain. */
const parentOf = new WeakMap();

function chainFrom(head) {
  const chain = [head];
  const nexts = couplings.get(head) || [];
  for (const g of nexts) chain.push(...chainFrom(g));
  return chain;
}

/**
 * Create a gear: a Group whose children are a cylinder body plus one box per
 * tooth. Pitch radius = module * teeth / 2.
 */
export function makeGear({ name, teeth, module: m = 1 }) {
  if (!Number.isInteger(teeth) || teeth < 3) {
    throw new Error(`teeth must be an integer >= 3, got ${teeth}`);
  }

  const pitchRadius = m * teeth / 2;

  const group = new THREE.Group();
  group.name = name;
  group.userData = { name, teeth, module: m, pitchRadius };

  // Body cylinder (axis along y by default -> rotate to align with z).
  const bodyRadius = pitchRadius - m * 0.5; // dedendum
  const width = m * 2;
  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(bodyRadius, bodyRadius, width, Math.max(16, teeth)),
    new THREE.MeshStandardMaterial({ color: 0x9aa5b1, metalness: 0.6, roughness: 0.4 })
  );
  body.rotation.x = Math.PI / 2;
  group.add(body);

  // Teeth boxes evenly spaced around the pitch circle.
  const toothMaterial = new THREE.MeshStandardMaterial({ color: 0xd97706, metalness: 0.4, roughness: 0.35 });
  const toothLength = m;      // radial extent beyond the body
  const toothWidth = m * 0.9; // tangential thickness
  for (let i = 0; i < teeth; i++) {
    const tooth = new THREE.Mesh(new THREE.BoxGeometry(toothLength, toothWidth, width), toothMaterial);
    tooth.userData.isTooth = true;
    const angle = (i / teeth) * Math.PI * 2;
    tooth.position.set(
      Math.cos(angle) * (bodyRadius + toothLength / 2),
      Math.sin(angle) * (bodyRadius + toothLength / 2),
      0
    );
    tooth.rotation.z = angle;
    group.add(tooth);
  }

  return group;
}

/**
 * Couple two gears in mesh: place `driven` along +x from `driver` so that the
 * pitch circles touch exactly, and register the coupling.
 * Returns the ordered train [root, ..., driver, driven].
 */
export function coupleGears(driver, driven) {
  const distance =
    driver.userData.pitchRadius + driven.userData.pitchRadius;

  // Place driven on the x axis through the driver's center.
  driven.position.set(driver.position.x + distance, driver.position.y, driver.position.z);

  if (!couplings.has(driver)) couplings.set(driver, []);
  couplings.get(driver).push(driven);
  parentOf.set(driven, driver);

  // Walk back to the head of the chain, then return it in order.
  let head = driver;
  while (parentOf.has(head)) head = parentOf.get(head);
  return chainFrom(head);
}

/**
 * Drive a train: set the head gear's rotation.z and propagate downstream,
 * alternating sense with the ratio of upstream teeth to own teeth:
 *   angle_i = -angle_(i-1) * teeth_(i-1) / teeth_i
 */
export function driveTrain(train, driverAngle) {
  let upstreamAngle = null;
  let upstreamTeeth = null;
  for (let i = 0; i < train.length; i++) {
    const gear = train[i];
    if (i === 0) {
      gear.rotation.z = driverAngle;
    } else {
      gear.rotation.z = -upstreamAngle * (upstreamTeeth / gear.userData.teeth);
    }
    upstreamAngle = gear.rotation.z;
    upstreamTeeth = gear.userData.teeth;
  }
  return train;
}

