import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { makeGear, coupleGears, driveTrain } from '../src/gearTrain.js';

describe('gear train', () => {
  it('turns an 8t pinion -> 24t wheel by -PI/3 for a PI driver turn', () => {
    const pinion = makeGear({ name: 'pinion', teeth: 8 });
    const wheel = makeGear({ name: 'wheel', teeth: 24 });
    const train = coupleGears(pinion, wheel);

    driveTrain(train, Math.PI);

    // ratio = -8/24 = -1/3, so wheel angle = -PI * (1/3)
    expect(wheel.rotation.z).toBeCloseTo(-Math.PI / 3, 12);
    expect(pinion.rotation.z).toBeCloseTo(Math.PI, 12);
  });

  it('matches the alternating ratio formula for an 8 -> 24 -> 12 chain', () => {
    const a = makeGear({ name: 'a', teeth: 8 });
    const b = makeGear({ name: 'b', teeth: 24 });
    const c = makeGear({ name: 'c', teeth: 12 });
    const train = coupleGears(coupleGears(a, b), c);
    expect(train.map((g) => g.userData.teeth)).toEqual([8, 24, 12]);

    const driverAngle = Math.PI * 2; // full driver turn
    driveTrain(train, driverAngle);

    // Expected final angle from the alternating ratio formula:
    let expected = driverAngle;
    for (let i = 1; i < train.length; i++) {
      expected = -expected * (train[i - 1].userData.teeth / train[i].userData.teeth);
    }

    expect(c.rotation.z).toBeCloseTo(expected, 12);
    // Sanity: full turn through 8/24 then inverted 24/12 gives +2PI/3.
    expect(expected).toBeCloseTo((Math.PI * 2) / 3, 12);
    expect(b.rotation.z).toBeCloseTo(-driverAngle * (8 / 24), 12);
  });

  it('places coupled gears exactly one sum-of-pitch-radii apart', () => {
    const m = 2;
    const p = makeGear({ name: 'p', teeth: 10, module: m });
    const w = makeGear({ name: 'w', teeth: 30, module: m });
    coupleGears(p, w);

    const centerDistance = Math.hypot(
      w.position.x - p.position.x,
      w.position.y - p.position.y
    );
    const expected = p.userData.pitchRadius + w.userData.pitchRadius;

    expect(centerDistance).toBeCloseTo(expected, 9); // within 1e-9
    expect(centerDistance - expected).toBeLessThan(1e-9);
    expect(Math.abs(centerDistance - expected)).toBeLessThan(1e-9);
  });

  it('builds one tooth mesh per tooth', () => {
    for (const teeth of [8, 12, 24, 57]) {
      const gear = makeGear({ name: `g${teeth}`, teeth });
      expect(gear).toBeInstanceOf(THREE.Group);
      expect(gear.userData.teeth).toBe(teeth);
      const toothMeshes = gear.children.filter((child) => child.userData.isTooth);
      expect(toothMeshes.length).toBe(teeth);
    }
  });
});

